mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Bid_Evaluation_Expert sd on sd.Sec_Id=sec.Sec_Id where sd.Bee_Id=#{beeId}

select
sec.Sec_Name as secName,
sec.Sec_Code as secCode,
mn.*
from  Sec_Bid_Evaluation_Expert mn
left join  Sec_Info sec on sec.Sec_Id=mn.Sec_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.Bee_Evaluation_Method = #{params.beeEvaluationMethod}


    and mn.Sec_Id = #{params.secId}


    and sec.Sec_Name like concat('%',#{params.secName},'%')


    order by mn.${params.sortFiled} ${params.sortType}

limit #{params.start},#{params.size}

select
count(1)
from  Sec_Bid_Evaluation_Expert mn
left join  Sec_Info sec on sec.Sec_Id=mn.Sec_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.Bee_Evaluation_Method = #{params.beeEvaluationMethod}


    and mn.Sec_Id = #{params.secId}


    and sec.Sec_Name like concat('%',#{params.secName},'%')
